ST.xhtml:
{region "§0 Decodage position M3"}
// === 🧩 §0 DÉCODAGE POSITION M3 (migré de PRG_02, AF-02 TBD §8 #5) ===
// PRG_02_Acquisition s'exécute avant ce POU (rang 01 < 05) : HwIn.Translation est
// disponible au même scan. Le décodage des capteurs M3 est propriété de PRG_05.
instPosDecoderM3(
    SensorTremie      := PRG_02_Acquisition.HwIn.Translation.M3_PosTremie_DI,
    SensorPV          := PRG_02_Acquisition.HwIn.Translation.M3_PosPV_DI,
    SensorP2          := PRG_02_Acquisition.HwIn.Translation.M3_PosPVP2_DI,
    SensorP1          := PRG_02_Acquisition.HwIn.Translation.M3_PosP1_DI,
    SensorMaintenance := PRG_02_Acquisition.HwIn.Translation.M3_PosMaintenance_DI
);

// 📤 Publication des faits M3 dans le bus PRG_05 (consommés par PRG_07)
Data.TranslationPosTremie      := instPosDecoderM3.TranslationPosTremie;
Data.TranslationPosPV          := instPosDecoderM3.TranslationPosPV;
Data.TranslationPosP2          := instPosDecoderM3.TranslationPosP2;
Data.TranslationPosP1          := instPosDecoderM3.TranslationPosP1;
Data.TranslationPosMaintenance := instPosDecoderM3.TranslationPosMaintenance;
Data.TranslationAtTremie      := instPosDecoderM3.TranslationAtTremie;
Data.TranslationAtPV          := instPosDecoderM3.TranslationAtPV;
Data.TranslationAtP2          := instPosDecoderM3.TranslationAtP2;
Data.TranslationAtP1          := instPosDecoderM3.TranslationAtP1;
Data.TranslationAtMaintenance := instPosDecoderM3.TranslationAtMaintenance;
Data.M3_LimitSwitchFwd       := instPosDecoderM3.LimitSwitchFwd;
Data.M3_LimitSwitchRev       := instPosDecoderM3.LimitSwitchRev;
Data.M3_SensorWordIncoherent := instPosDecoderM3.Incoherent;
Data.M3_SensorsWord            := instPosDecoderM3.SensorsWord;
{endregion}

{region "§0 Interlock hauteur M1/M2"}
// === 🚧 §0 INTERLOCK HAUTEUR M1/M2 (risque collision translation) ===
// PRG_02_Acquisition s'exécute avant ce POU dans la MainTask (rang 01 < 05) : lecture
// du même scan, aucun retard. Bypass = maintenance consciente, doctrine ST_BypassTranslation.
// ⚠️ Une position encodeur incohérente (hors plage OU homing suspect,
// FB_Encoder_Safety) ne doit PAS pouvoir se lire comme "≥ seuil" par accident — fail-safe :
// hauteur non confirmée = interlock actif (comme une hauteur insuffisante), sauf bypass.
// 🔒 Bypass.Global NE lève PLUS cet interlock (contrairement aux autres
// causes de l'axe M3) — risque de collision jugé trop grave pour être levé par un bypass
// générique. Seul Bypass.MinHeight (dédié, conscient) lève l'anti-collision hauteur.
M3_HeightInterlockOk := GVL_IHM.TranslationM3.Bypass.MinHeight
                        OR (PRG_02_Acquisition.Data.M1_HomedAndReliable
                            AND PRG_02_Acquisition.Data.M2_HomedAndReliable
                            AND (PRG_02_Acquisition.Data.Encoders.M1.CablePosM >= GVL_PERSISTENT._TranslationMinHeightM1M2_M)
                            AND (PRG_02_Acquisition.Data.Encoders.M2.CablePosM >= GVL_PERSISTENT._TranslationMinHeightM1M2_M));
TranslationState.HeightInterlockBlocking := NOT M3_HeightInterlockOk;

{endregion}

{region "§0bis Coupure dure limite translation"}
// === 🚧 §0bis COUPURE DURE (LimitSwitchRev) — bascule sur P1 si Maintenance interdite ===
// LimitSwitchFwd/Rev protègent nativement Trémie/Maintenance
// (§5bis FB_Translation : coupure immédiate, sans rampe, dès que CommandedDirection insiste
// dans l'extrémité). P1/P2 n'ont aucune protection dure équivalente — seul le verrou souple
// (arrival-lock) les couvre. Quand Maintenance est interdite, la coupure dure doit protéger
// P1 comme si c'était l'extrémité réelle : mot 00001 (P1=0 ET Maintenance=1), UN CRAN AVANT
// la vraie extrémité Maintenance (00000) — backup si le verrou souple a déjà échoué à arrêter
// avant P1, garde la machine hors de la zone interdite plutôt que d'attendre le vrai fond.
M3_LimitSwitchRevEffective := SEL(PRG_03_Modes_Cycle.Auth.MaintenanceM3TargetEnable,
                                   NOT instPosDecoderM3.TranslationPosP1 AND instPosDecoderM3.TranslationPosMaintenance,
                                   instPosDecoderM3.LimitSwitchRev);

// 🔒 §0ter STABILISATION BISTABLE FINS DE COURSE EXTRÊMES (Trémie & Maintenance/P1)
// Maintient la détection stable à 1 même si le capteur physique vibre ou saute brièvement.
// Se libère uniquement sur un mouvement effectif dans le SENS INVERSE (dégagement).
IF instPosDecoderM3.LimitSwitchFwd THEN
    M3_LimitSwitchFwdStable := TRUE;
ELSIF M3_Direction_Active = -1 THEN
    M3_LimitSwitchFwdStable := FALSE;
END_IF;

IF M3_LimitSwitchRevEffective THEN
    M3_LimitSwitchRevStable := TRUE;
ELSIF M3_Direction_Active = 1 OR (PRG_03_Modes_Cycle.Auth.MaintenanceM3TargetEnable AND NOT instPosDecoderM3.LimitSwitchRev) THEN
    M3_LimitSwitchRevStable := FALSE;
END_IF;

// 🔒 §0quater MÉMORISATION DU DERNIER POINT ATTEINT (front → jeton unique)
// PositionDecoder n'émet qu'un front transitoire (1 cycle) par capteur, montant OU descendant
// SELON LE SENS (voir FB_Translation_PositionDecoder.st) — mémorisé ici pour
// tenir le niveau nécessaire au débounce (100ms) + verrou anti-rebond (§4ter DirectionAtArrival)
// de FB_Translation, et pour l'affichage IHM. MUTUELLEMENT EXCLUSIFS : un nouveau front RAZ tous
// les autres (jeton "dernier point franchi" unique). Libéré
// (RAZ complet) UNIQUEMENT sur mouvement CONFIRMÉ (fréquence réelle mesurée, pas juste la consigne
// de sens) soutenu ≥1.5s — pas un rebond capteur ni un changement de sens instantané.
M3_ConfirmedMoving := (UINT_TO_REAL(PRG_02_Acquisition.Data.M3_ActualFrequencyHz_Filtered) / 100.0) > 0.5;
TonM3ConfirmedMoving(IN := M3_ConfirmedMoving, PT := T#1s500ms);

IF instPosDecoderM3.TranslationAtTremie THEN
    M3_AtTremieStable := TRUE; M3_AtPVStable := FALSE; M3_AtP2Stable := FALSE; M3_AtP1Stable := FALSE; M3_AtMaintenanceStable := FALSE;
ELSIF instPosDecoderM3.TranslationAtPV THEN
    M3_AtPVStable := TRUE; M3_AtTremieStable := FALSE; M3_AtP2Stable := FALSE; M3_AtP1Stable := FALSE; M3_AtMaintenanceStable := FALSE;
ELSIF instPosDecoderM3.TranslationAtP2 THEN
    M3_AtP2Stable := TRUE; M3_AtTremieStable := FALSE; M3_AtPVStable := FALSE; M3_AtP1Stable := FALSE; M3_AtMaintenanceStable := FALSE;
ELSIF instPosDecoderM3.TranslationAtP1 THEN
    M3_AtP1Stable := TRUE; M3_AtTremieStable := FALSE; M3_AtPVStable := FALSE; M3_AtP2Stable := FALSE; M3_AtMaintenanceStable := FALSE;
ELSIF instPosDecoderM3.TranslationAtMaintenance THEN
    M3_AtMaintenanceStable := TRUE; M3_AtTremieStable := FALSE; M3_AtPVStable := FALSE; M3_AtP2Stable := FALSE; M3_AtP1Stable := FALSE;
ELSIF TonM3ConfirmedMoving.Q THEN
    // Mouvement réel confirmé ≥1.5s sans nouveau front : on a vraiment quitté le dernier point.
    M3_AtTremieStable := FALSE; M3_AtPVStable := FALSE; M3_AtP2Stable := FALSE; M3_AtP1Stable := FALSE; M3_AtMaintenanceStable := FALSE;
END_IF;

{endregion}

{region "§1 Arbitrage cible et direction"}
// === 🔀 §1 ARBITRAGE DU SÉLECTEUR DE CIBLE ET DE LA DIRECTION ===

IF PRG_03_Modes_Cycle.Auth.Mode = E_Mode.SEMI_AUTO THEN
    // Pont SEMI_AUTO : consomme la demande du séquenceur de cycle.
    // FB_Cycle produit TranslationCmd.Start conditionné par CycleMotionPermit (homme-mort 3s, D2).
    M3_PositioningActive  := TRUE;
    SelTarget    := PRG_03_Modes_Cycle.instCycleSemiAuto.TranslationCmd.Target;
    M3_StartStop_Active  := PRG_03_Modes_Cycle.instCycleSemiAuto.TranslationCmd.Start;

    // 🔒 Direction/vitesse M3 uniquement si le cycle commande réellement le mouvement (Start).
    // Sans Start, M3 reste à l'arrêt (direction=0, vitesse=0) — aucun mouvement parasite.
    IF M3_StartStop_Active THEN
        M3_SpeedCmd_Active := 100.0;
        // Direction déduite de la cible (Trémie=1 → Fwd, sinon Rev)
        IF SelTarget = 1 THEN
            M3_Direction_Active := 1;
        ELSE
            M3_Direction_Active := -1;
        END_IF;
    ELSE
        M3_SpeedCmd_Active := 0.0;
        M3_Direction_Active := 0;
    END_IF;
ELSIF (PRG_03_Modes_Cycle.Auth.Mode = E_Mode.MAINT_N1)
   OR (PRG_03_Modes_Cycle.Auth.Mode = E_Mode.MAINT_N2) THEN
    M3_PositioningActive := GVL_IHM.TranslationM3.Cmd.SelPositioning;
    SelTarget := 0;

    IF NOT GVL_IHM.Modes.Cmd.TglJoystickMaster AND GVL_IHM.TranslationM3.Cmd.BtnFwd THEN
        M3_Direction_Active := 1;
    ELSIF NOT GVL_IHM.Modes.Cmd.TglJoystickMaster AND GVL_IHM.TranslationM3.Cmd.BtnRev THEN
        M3_Direction_Active := -1;
    ELSIF GVL_IHM.Modes.Cmd.TglJoystickMaster THEN
        M3_Direction_Active := PRG_02_Acquisition.Data.JoystickDirectionX;
    ELSE
        M3_Direction_Active := 0;
    END_IF;

    // Homme-mort exigé même pour boutons IHM en MAINT_N1/N2
    // (AF_Partie-08 §6, AF_Partie-11 §4.2) — pas seulement pour un pilotage joystick réel.
    // TglJoystickMaster consolidé — un seul switch machine (GVL_IHM.Modes.Cmd).
    M3_StartStop_Active := (M3_Direction_Active <> 0)
                           AND (GVL_IHM.TranslationM3.Bypass.Global
                                OR NOT GVL_IHM.Modes.Cmd.TglJoystickMaster
                                OR GVL_IHM.Modes.Cmd.TglJoystickMaster)
                           AND PRG_02_Acquisition.Data.JoystickDeadmanArmed
                           AND M3_HeightInterlockOk; // Hauteur mini M1/M2 (risque collision)

    FreqPct := SEL(GVL_IHM.TranslationM3.Cmd.SetFreq_Hz > 0.0,
                  100.0,
                  (GVL_IHM.TranslationM3.Cmd.SetFreq_Hz / SEL(GVL_PERSISTENT._TranslationMaxFreq_Hz > 0.0, 50.0, GVL_PERSISTENT._TranslationMaxFreq_Hz)) * 100.0);
    // 🕹️ Si TglJoystickMaster (global) = TRUE, le manche (0..100%) est mis à l'échelle sur la consigne SetFreq_Hz (ou 100% si non renseignée).
    M3_SpeedCmd_Active := SEL(GVL_IHM.Modes.Cmd.TglJoystickMaster,
                              FreqPct,
                              (PRG_02_Acquisition.Data.JoystickSpeedPctX / 100.0) * FreqPct);
ELSE
    M3_PositioningActive := FALSE;
    SelTarget    := 0;
    M3_StartStop_Active  := FALSE;
    M3_Direction_Active  := 0;
    M3_SpeedCmd_Active   := 0.0;
END_IF;

// InvertDirection est appliqué dans FB_Translation (InvertDriveDirection), uniquement au mot
// de commande variateur en sortie — M3_Direction_Active reste partout le sens sémantique réel.

M3_SpeedCmd_Active := LIMIT(0.0, ABS(M3_SpeedCmd_Active), 100.0);

IF (SelTarget = 4) AND NOT PRG_03_Modes_Cycle.Auth.MaintenanceM3TargetEnable THEN
    SelTarget := 0;
END_IF;

// 🩺 InputModuleFault (AF06 §3bis) : un module DI TOR hors service rend indisponibles
// les retours frein/thermique/positions du VH_0808ETP/VH_0800END portant M3 — rampe rapide.
M3_SafeStop_Active := PRG_02_Acquisition.Data.InputModuleFault;

// En mode manuel (SelTarget=0), n'importe quel des 3 points d'arrêt (Trémie/P1/Maintenance)
// arme le verrou anti-rebond §4ter de FB_Translation (DirectionAtArrival). Mot EXACT
// (TranslationAtXxx), pas le cumulatif (TranslationPosXxx) — front franc à l'arrivée quel que
// soit le sens de venue (voir FB_Translation_PositionDecoder.st).
CASE SelTarget OF
    1: M3_PositionSensorTarget := M3_AtTremieStable;
    2: M3_PositionSensorTarget := M3_AtP2Stable;
    3: M3_PositionSensorTarget := M3_AtP1Stable;
    4: M3_PositionSensorTarget := M3_AtMaintenanceStable;
ELSE
    IF M3_Direction_Active = 1 THEN
        // En Marche Avant (+1 vers Trémie) : seule Trémie est le point d'arrêt automatique
        M3_PositionSensorTarget := M3_AtTremieStable;
    ELSIF M3_Direction_Active = -1 THEN
        // En Marche Arrière (-1 vers Maintenance) :
        // - Si Maintenance autorisée -> arrêt sur Maintenance
        // - Si Maintenance interdite -> arrêt sur P1
        IF PRG_03_Modes_Cycle.Auth.MaintenanceM3TargetEnable THEN
            M3_PositionSensorTarget := M3_AtMaintenanceStable;
        ELSE
            M3_PositionSensorTarget := M3_AtP1Stable;
        END_IF;
    ELSE
        M3_PositionSensorTarget := FALSE;
    END_IF;
END_CASE;


{endregion}

{region "§1bis Securite M3"}
// === 🛡️ §1bis SÉCURITÉ M3 (FB_Safety_Translation, câblée en parallèle visible) ===
// ⚠️ Ordre d'appel volontaire : la safety lit ici le BrakeReleaseRequest et le
// BrakeCmd du SCAN PRÉCÉDENT d'instTranslationM3 (elle est appelée avant), soit un retard
// d'un scan. Bénin : BrakeReleaseRequest ne change pas plus vite qu'un scan MainTask 10 ms
// sur une commande frein.
instSafetyTranslationM3(
    Enable                  := (PRG_03_Modes_Cycle.Auth.Mode <> E_Mode.DISABLE),
    Reset                   := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged   := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    Mode                    := PRG_03_Modes_Cycle.Auth.Mode,
    JoystickOnline          := PRG_02_Acquisition.instDiagCanOpen.DeviceJoystick.Online,
    JoystickOperational     := PRG_02_Acquisition.instDiagCanOpen.DeviceJoystick.Operational,
    HeartbeatIhmOk          := GVL_IHM.Commun.HeartbeatIhmOk,
    PhaseRotationOk         := PRG_02_Acquisition.HwIn.Machine.PhaseRotationOk_DI,
    BrakeThermalFeedback    := NOT PRG_02_Acquisition.HwIn.Machine.M1_M2_M3_BrakeThermalOk_DI,
    DriveOnline             := PRG_02_Acquisition.instDiagEthercat.DeviceVariateur.Online,
    DriveOperational        := PRG_02_Acquisition.instDiagEthercat.DeviceVariateur.Operational,
    DriveStatusWord         := PRG_02_Acquisition.Data.M3_StatusWord_Filtered,
    DriveActualFreqHz       := UINT_TO_REAL(PRG_02_Acquisition.Data.M3_ActualFrequencyHz_Filtered) / 100.0,
    BrakeFeedback           := SEL(GVL_IHM.TranslationM3.Bypass.ContactorFeedback OR GVL_IHM.TranslationM3.Bypass.Global, PRG_02_Acquisition.HwIn.Translation.M3_BrakeIsOpen_DI, instTranslationM3.BrakeReleaseRequest),
    BrakeCmd                := instTranslationM3.BrakeReleaseRequest,
    Direction               := M3_Direction_Active,
    LimitSwitchFwd          := M3_LimitSwitchFwdStable,
    LimitSwitchRev          := M3_LimitSwitchRevStable,
    SensorWordIncoherent    := instPosDecoderM3.Incoherent,
    BypassGlobal            := GVL_IHM.TranslationM3.Bypass.Global,
    BypassOperatorComm      := GVL_IHM.TranslationM3.Bypass.OperatorComm,
    BypassDriveComm         := GVL_IHM.TranslationM3.Bypass.DriveComm,
    BypassPhaseRotation     := GVL_IHM.TranslationM3.Bypass.PhaseRotation,
    BypassBrakeThermal      := GVL_IHM.TranslationM3.Bypass.BrakeThermal,
    BypassMecaB             := GVL_IHM.TranslationM3.Bypass.MecaB,
    BypassMecaA             := GVL_IHM.TranslationM3.Bypass.MecaA,
    BypassLimitSwitch       := GVL_IHM.TranslationM3.Bypass.LimitSwitch,
    BypassSensorIncoherent  := GVL_IHM.TranslationM3.Bypass.SensorIncoherent,
    BypassSafety            := GVL_IHM.TranslationM3.Bypass.Safety,
    BypassProcess           := GVL_IHM.TranslationM3.Bypass.Process
);

// SafeStop réellement appliqué au mouvement = agrégat InputModuleFault OR safety M3
// (8 mécanismes) — aucune des deux causes ne doit être perdue.
M3_SafeStop_Aggregate := M3_SafeStop_Active OR instSafetyTranslationM3.SafeStop;

{endregion}

{region "§2 Pilotage translation M3"}
// === ⚙️ §2 EXÉCUTION PILOTAGE TRANSLATION M3 ===

instTranslationM3(
    Enable                  := (PRG_03_Modes_Cycle.Auth.Mode <> E_Mode.DISABLE),
    Reset                   := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged   := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    Mode                    := PRG_03_Modes_Cycle.Auth.Mode,
    StartStop               := M3_StartStop_Active,
    SafeStop                := M3_SafeStop_Aggregate,
    Direction               := M3_Direction_Active,
    InvertDriveDirection    := GVL_IHM.TranslationM3.Cmd.InvertDirection,
    SpeedTgt_Pct            := M3_SpeedCmd_Active,
    PositionSensorTarget    := M3_PositionSensorTarget,
    SlowdownSensorTremie       := instPosDecoderM3.TranslationPosPV,
    // Les 5 capteurs forment un code thermomètre cumulatif depuis la Trémie (voir
    // FB_Translation_PositionDecoder.st). Chaque zone est délimitée par "capteur PRÉCÉDENT retombé
    // à 0" ET "capteur de la zone encore à 1" — zone P2→P1 = NOT PosP2 AND PosP1 (mot 00011) ;
    // zone P1→Maintenance = NOT PosP1 AND PosMaintenance (mot 00001). Zones mutuellement exclusives,
    // chacune sa propre vitesse d'approche (CfgApproachSpeedP1_Hz / CfgApproachSpeedMaintenance_Hz).
    SlowdownSensorMaintenance  := (NOT instPosDecoderM3.TranslationPosP1) AND instPosDecoderM3.TranslationPosMaintenance,
    // Ralentissement P2→P1 UNIQUEMENT si P1 est un vrai point
    // d'arrêt (zone Maintenance NON autorisée). Zone Maintenance autorisée -> 100% vitesse jusqu'à
    // P1, ralentissement seulement après (zone P1→Maintenance, SlowdownSensorMaintenance ci-dessus).
    SlowdownSensorP1           := (NOT instPosDecoderM3.TranslationPosP2) AND instPosDecoderM3.TranslationPosP1
                                   AND NOT PRG_03_Modes_Cycle.Auth.MaintenanceM3TargetEnable,
    LimitSwitchFwd          := M3_LimitSwitchFwdStable,
    LimitSwitchRev          := M3_LimitSwitchRevStable,
    DriveStatusWord         := PRG_02_Acquisition.Data.M3_StatusWord_Filtered,
    DriveActualFreqHz       := UINT_TO_REAL(PRG_02_Acquisition.Data.M3_ActualFrequencyHz_Filtered) / 100.0,
    CfgRampAccelRate        := _TranslationRampAccelRate_Pct,
    CfgRampDecelNormalRate  := _TranslationRampDecelNormal_Pct,
    CfgRampDecelFastRate    := _TranslationRampDecelFast_Pct,
    ApproachSpeedTremieHz       := GVL_IHM.TranslationM3.Cfg.CfgApproachSpeedTremie_Hz,
    ApproachSpeedMaintenanceHz  := GVL_IHM.TranslationM3.Cfg.CfgApproachSpeedMaintenance_Hz,
    ApproachSpeedP1Hz           := GVL_IHM.TranslationM3.Cfg.CfgApproachSpeedP1_Hz,
    DriveFreqScaleMaxHz     := _TranslationMaxFreq_Hz,
    BrakeFeedback           := SEL(GVL_IHM.TranslationM3.Bypass.ContactorFeedback OR GVL_IHM.TranslationM3.Bypass.Global, PRG_02_Acquisition.HwIn.Translation.M3_BrakeIsOpen_DI, instTranslationM3.BrakeReleaseRequest),
    BypassContactorCheck    := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.ContactorFeedback,
    BypassLimitSwitch       := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.LimitSwitch
);

// 📐 Estimateur de position continue M3 (odométrie + recalage 5 capteurs)
instPosEstimatorM3(
    Enable               := (PRG_03_Modes_Cycle.Auth.Mode <> E_Mode.DISABLE),
    Reset                := PRG_07_Supervision.FaultMachineReset_IHM,
    DriveActualFreqHz    := TO_REAL(PRG_02_Acquisition.Data.M3_ActualFrequencyHz_Filtered) / 100.0,
    Direction            := M3_Direction_Active,
    SensorMaintenance    := instPosDecoderM3.TranslationPosMaintenance,
    SensorP1             := instPosDecoderM3.TranslationPosP1,
    SensorP2             := instPosDecoderM3.TranslationPosP2,
    SensorPV             := instPosDecoderM3.TranslationPosPV,
    SensorTremie         := instPosDecoderM3.TranslationPosTremie,
    PosMaintenanceM      := GVL_PERSISTENT._TranslationPosMaintenance_M,
    PosP1M               := GVL_PERSISTENT._TranslationPosP1_M,
    PosP2M               := GVL_PERSISTENT._TranslationPosP2_M,
    PosPVM               := GVL_PERSISTENT._TranslationPosPV_M,
    PosTremieM           := GVL_PERSISTENT._TranslationPosTremie_M,
    GainMetersPerHzSec   := GVL_PERSISTENT._TranslationGainMetersPerHzSec,
    PersistedPositionM   := GVL_PERSISTENT._TranslationPosEstimated_M,
    PersistedInitialized := GVL_PERSISTENT._TranslationPosEstimatedInitialized
);
// Recopie continue (reprise après reboot, doctrine _TranslationSetFreq_Hz) — pas de bridge dédié.
GVL_PERSISTENT._TranslationPosEstimated_M := instPosEstimatorM3.PositionEstimatedM;
GVL_PERSISTENT._TranslationPosEstimatedInitialized := instPosEstimatorM3.Initialized;


{endregion}

{region "§3 Publication demande translation"}
// === 📤 §3 PUBLICATION DEMANDE BRUTE TRANSLATION ===

TranslationFinalInterlockRequest.Enable := (PRG_03_Modes_Cycle.Auth.Mode <> E_Mode.DISABLE);
TranslationFinalInterlockRequest.Reset := PRG_07_Supervision.FaultMachineReset_IHM;
TranslationFinalInterlockRequest.PowerContactorEngaged := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI;
TranslationFinalInterlockRequest.SafeStop := M3_SafeStop_Aggregate;
TranslationFinalInterlockRequest.PowerCutOff := instSafetyTranslationM3.PowerCutOff;
TranslationFinalInterlockRequest.BrakeReleaseRequest := instTranslationM3.BrakeReleaseRequest;
TranslationFinalInterlockRequest.BrakeCommandOpenConfirmed := instTranslationM3.BrakeCommandOpenConfirmed;
TranslationFinalInterlockRequest.RequestedDriveControlWord := instTranslationM3.RequestedDriveControlWord;
TranslationFinalInterlockRequest.RequestedDriveFreqHz := instTranslationM3.RequestedDriveFreqHz;

{endregion}

{region "§4 Publication etat IHM"}
// === 📤 PUBLICATION ÉTAT TRANSLATION IHM (lecture seule) ===
TranslationState.FBState := instTranslationM3.Status.State;
TranslationState.Ready := instTranslationM3.Ready;
TranslationState.Busy := instTranslationM3.Status.Busy;
TranslationState.Done := instTranslationM3.Status.Done;
TranslationState.Error := instTranslationM3.Status.Error;
TranslationState.ErrorId := instTranslationM3.Status.ErrorId;
TranslationState.BrakeCmd := instTranslationM3.BrakeReleaseRequest;
TranslationState.BrakeCommandOpenConfirmed := instTranslationM3.BrakeCommandOpenConfirmed;
TranslationState.PositionReached := instTranslationM3.TargetReached;
TranslationState.DriveControlWord := instTranslationM3.RequestedDriveControlWord;
TranslationState.DriveFreqCmd_Hz := instTranslationM3.RequestedDriveFreqHz;
// 🎯 Cohérence sim : ActiveDirection/SpeedCmd_Pct n'affichent la
// consigne QUE si la commande variateur est réellement émise (RequestedDriveControlWord <> 0).
// Sinon, un interlock bloquant (hauteur, SafeStop…) laisserait l'IHM suggérer un mouvement
// qui n'a pas lieu ("je bouge mais ça bouge pas"). Affiche 0 quand c'est bloqué.
TranslationState.ActiveDirection := SEL(instTranslationM3.RequestedDriveControlWord <> 0, M3_Direction_Active, 0);
TranslationState.SpeedCmd_Pct := SEL(instTranslationM3.RequestedDriveControlWord <> 0, M3_SpeedCmd_Active, 0.0);
TranslationState.PositionTremie := instPosDecoderM3.TranslationPosTremie;
TranslationState.PositionPV := instPosDecoderM3.TranslationPosPV;
TranslationState.PositionP2 := instPosDecoderM3.TranslationPosP2;
TranslationState.PositionP1 := instPosDecoderM3.TranslationPosP1;
TranslationState.PositionMaintenance := instPosDecoderM3.TranslationPosMaintenance;
// Affichage IHM = M3_AtXxxStable (§0quater) — armé sur front
// (direction-dépendant), libéré sur mouvement réel confirmé ≥1.5s (pas juste un rebond capteur
// ni un changement de sens instantané). Même signal que celui consommé par M3_PositionSensorTarget.
TranslationState.AtTremie := M3_AtTremieStable;
TranslationState.AtPV := M3_AtPVStable;
TranslationState.AtP2 := M3_AtP2Stable;
TranslationState.AtP1 := M3_AtP1Stable;
TranslationState.AtMaintenance := M3_AtMaintenanceStable;
TranslationState.EstimatedPosM3_M := instPosEstimatorM3.PositionEstimatedM;
TranslationState.SensorsWord := instPosDecoderM3.SensorsWord;
TranslationState.SensorWordIncoherent := instPosDecoderM3.Incoherent;
TranslationState.LimitSwitchFwd := M3_LimitSwitchFwdStable;
TranslationState.LimitSwitchRev := M3_LimitSwitchRevStable;
TranslationState.DriveActualFreq_Hz := TO_REAL(PRG_02_Acquisition.Data.M3_ActualFrequencyHz_Filtered) / 100.0;
TranslationState.DriveThermalOk := PRG_02_Acquisition.HwIn.Translation.M3_ThermalOK_DI;
TranslationState.FinalInterlockState := PRG_06_Outputs.instTranslationOutputInterlockM3.Status.State;
TranslationState.FinalInterlockReason := PRG_06_Outputs.instTranslationOutputInterlockM3.Reason;
TranslationState.FinalInterlockError := PRG_06_Outputs.instTranslationOutputInterlockM3.Status.Error;
TranslationState.FinalInterlockErrorId := PRG_06_Outputs.instTranslationOutputInterlockM3.Status.ErrorId;
TranslationState.FinalBrakeTimeoutElapsed := PRG_06_Outputs.instTranslationOutputInterlockM3.BrakeTimeoutElapsed;
TranslationState.DriveCommReady := (PRG_02_Acquisition.Data.M3_StatusWord_Filtered AND 16#0080) <> 0;
TranslationState.DrivePowerReady := (PRG_02_Acquisition.Data.M3_StatusWord_Filtered AND 16#0001) <> 0;
TranslationState.MaintenanceTargetEnable := PRG_03_Modes_Cycle.Auth.MaintenanceM3TargetEnable;
TranslationState.SimulationModeActive := GVL_Simulation.SimulationModeActive;

// 🛡️ Producteur unique (CODE_QUALITY_STANDARDS §5) : la safety M3 (instSafetyTranslationM3)
// est la source de tous les diagnostics de sécurité (ErrorLimitSwitch/ErrorSensorIncoherent).
// Les erreurs propres au mouvement (frein, variateur AC600) restent sur TranslationState.ErrorId
// ci-dessus, bitfield différent, jamais mélangé.
TranslationSafety.SafeStop := M3_SafeStop_Aggregate;
TranslationSafety.PowerCutOff := instSafetyTranslationM3.PowerCutOff;
TranslationSafety.Error := instSafetyTranslationM3.Status.Error;
TranslationSafety.ErrorId := instSafetyTranslationM3.Status.ErrorId;
TranslationSafety.ErrorOperatorComm := instSafetyTranslationM3.ErrorOperatorComm;
TranslationSafety.ErrorDriveComm := instSafetyTranslationM3.ErrorDriveComm;
TranslationSafety.ErrorPhaseRotation := instSafetyTranslationM3.ErrorPhaseRotation;
TranslationSafety.ErrorBrakeThermal := instSafetyTranslationM3.ErrorBrakeThermal;
TranslationSafety.ErrorMecaB := instSafetyTranslationM3.ErrorMecaB;
TranslationSafety.ErrorMecaA := instSafetyTranslationM3.ErrorMecaA;
TranslationSafety.ErrorLimitSwitch := instSafetyTranslationM3.ErrorLimitSwitch;
TranslationSafety.ErrorSensorIncoherent := instSafetyTranslationM3.ErrorSensorIncoherent;
TranslationSafety.PowerCutOffSafety := PRG_06_Outputs.M3PowerCutOffSafetyInfo;
TranslationSafety.SafeStopSafety := PRG_06_Outputs.M3SafeStopSafetyInfo;
TranslationSafety.BlockedBySafety := PRG_06_Outputs.M3BlockedBySafetyInfo;

// === 🔌 PUBLICATION BUS INTER-PRG (Data : ST_TranslationInterPrg) ===
// Copie des structs internes vers le bus de sortie (producteur unique).
Data.TranslationFinalInterlockRequest := TranslationFinalInterlockRequest;
Data.TranslationState                 := TranslationState;
Data.TranslationSafety                := TranslationSafety;

{endregion}

// === IMPLEMENTATION ===

{region "§1 Gate neutralisation"}
// 🛑 1. GATE — neutralisation si désactivé
IF NOT Enable THEN
    // 🛡️ Status.ErrorId conservé : la cause du dernier défaut reste visible IHM.
    // Status.Error en miroir de cette cause ; les sorties restent fail-safe (lignes ci-dessous).
    Status.Error := (Status.ErrorId <> 16#0000);
    SafeStop := FALSE;
    PowerCutOff := FALSE;
    ErrorOperatorComm := FALSE;
    ErrorDriveComm := FALSE;
    ErrorPhaseRotation := FALSE;
    ErrorBrakeThermal := FALSE;
    ErrorMecaB := FALSE;
    ErrorMecaA := FALSE;
    ErrorLimitSwitch := FALSE;
    ErrorSensorIncoherent := FALSE;
    TonMecaB(IN := FALSE);
    TonMecaA(IN := FALSE);
    TonLimitSwitchOverrun(IN := FALSE);
    TonStartupWarmup(IN := FALSE);
    Status.State := E_State.DISABLED;
    Status.Busy := FALSE; Status.Done := FALSE; Ready := FALSE;
    RETURN;
END_IF;

{endregion}

{region "§1bis Initialisation et bypass global"}
Ready := TRUE;
ResetEdge(CLK := Reset);

// 🧹 Initialisation au premier scan : purge des résidus RAM d'un Online Change / Warm Start et évitement des alarmes transitoires
IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    Status.ErrorId := 16#0000;
    RETURN;
END_IF;

// 🌐 BYPASS GLOBAL : si actif → force Status.ErrorId = 0 et saute toutes les vérifications
// (les bits d'erreur resteraient coincés si on ne les nettoie pas)
IF BypassGlobal THEN
    Status.ErrorId := 16#0000;
    TonMecaB(IN := FALSE);
    TonMecaA(IN := FALSE);
END_IF;

{endregion}

{region "§2 Diagnostics et protections translation"}
// ⚠️ ResetEdge doit être traité même si bypass actif, pour que le reset IHM fonctionne.
// On ne l'exécute que si on n'est PAS en bypass global (sinon ErrorId déjà à 0).
IF NOT BypassGlobal THEN
    // ⏱️ Temporisation 3s de mise en route des bus de terrain au boot (EtherCAT / CANopen / Modbus IHM)
    TonStartupWarmup(IN := Enable, PT := T#3s);

    // 🔍 2. PERTE COMMUNICATION OPÉRATEUR (bit0) — joystick CAN ou heartbeat IHM.
    IF TonStartupWarmup.Q AND NOT (BypassProcess OR BypassOperatorComm) THEN
        IF (NOT JoystickOnline OR NOT JoystickOperational OR NOT HeartbeatIhmOk) THEN
            Status.ErrorId := Status.ErrorId OR 16#0001;
        ELSE
            Status.ErrorId := Status.ErrorId AND 16#FFFE; (* Effacement auto si la com repasse saine *)
        END_IF;
    ELSIF NOT TonStartupWarmup.Q THEN
        Status.ErrorId := Status.ErrorId AND 16#FFFE; (* Inhibition pendant l'initialisation boot *)
    END_IF;
    IF ResetEdge.Q THEN Status.ErrorId := Status.ErrorId AND 16#FFFE; END_IF;

    // 🔍 2bis. PERTE ETHERCAT VARIATEUR M3 (bit1)
    IF TonStartupWarmup.Q AND NOT (BypassProcess OR BypassDriveComm) THEN
        IF (NOT DriveOnline OR NOT DriveOperational) THEN
            Status.ErrorId := Status.ErrorId OR 16#0002;
        ELSE
            Status.ErrorId := Status.ErrorId AND 16#FFFD; (* Effacement auto si l'EtherCAT variateur M3 repasse sain *)
        END_IF;
    ELSIF NOT TonStartupWarmup.Q THEN
        Status.ErrorId := Status.ErrorId AND 16#FFFD; (* Inhibition pendant l'initialisation boot *)
    END_IF;
    IF ResetEdge.Q THEN Status.ErrorId := Status.ErrorId AND 16#FFFD; END_IF;

    // 🔍 3. MAUVAISE ROTATION DE PHASE (bit2)
    IF NOT (BypassProcess OR BypassPhaseRotation) THEN
        IF NOT PhaseRotationOk THEN
            Status.ErrorId := Status.ErrorId OR 16#0004;
        END_IF;
    END_IF;
    IF ResetEdge.Q THEN Status.ErrorId := Status.ErrorId AND 16#FFFB; END_IF;

    // 🔍 3ter. THERMIQUE FREIN COMMUN M1/M2/M3 (bit3)
    IF NOT (BypassSafety OR BypassBrakeThermal) THEN
        IF BrakeThermalFeedback THEN
            Status.ErrorId := Status.ErrorId OR 16#0008;
        END_IF;
    END_IF;
    IF ResetEdge.Q THEN Status.ErrorId := Status.ErrorId AND 16#FFF7; END_IF;

    // 🔍 3quater. INCOHÉRENCE À L'ARRÊT (Méca B — bit4)
    IF NOT (BypassSafety OR BypassMecaB) THEN
        IF NOT HeartbeatIhmOk THEN
            UncommandedActiveB := (ABS(DriveActualFreqHz) > 0.5) OR DriveStatusWord.0 OR BrakeFeedback;
        ELSIF (Direction = 0) AND NOT BrakeCmd THEN
            UncommandedActiveB := DriveStatusWord.0 OR BrakeFeedback;
        ELSE
            UncommandedActiveB := FALSE;
        END_IF;
        TonMecaB(IN := UncommandedActiveB, PT := PostRampTimeout);
        IF TonMecaB.Q THEN Status.ErrorId := Status.ErrorId OR 16#0010; END_IF;
    ELSE
        TonMecaB(IN := FALSE);
    END_IF;
    IF ResetEdge.Q THEN Status.ErrorId := Status.ErrorId AND 16#FFEF; END_IF;

    // 🔍 3quinquies. MOUVEMENT NON COMMANDÉ (Méca A — bit5)
    IF NOT (BypassSafety OR BypassMecaA) THEN
        IF (Direction = 0) AND NOT BrakeCmd THEN
            UncommandedActiveA := ABS(DriveActualFreqHz) > 0.5;
        ELSE
            UncommandedActiveA := FALSE;
        END_IF;
        TonMecaA(IN := UncommandedActiveA, PT := T#1S);
        IF TonMecaA.Q THEN Status.ErrorId := Status.ErrorId OR 16#0020; END_IF;
    ELSE
        TonMecaA(IN := FALSE);
    END_IF;
    IF ResetEdge.Q THEN Status.ErrorId := Status.ErrorId AND 16#FFDF; END_IF;

    // 🔍 3sexies. SURVEILLANCE ESCALADE FIN DE COURSE (bit6)
    IF (BypassSafety OR BypassLimitSwitch) THEN
        // Nettoie le bit 6 résiduel (posé avant activation du bypass)
        Status.ErrorId := Status.ErrorId AND 16#FFBF;
        TonLimitSwitchOverrun(IN := FALSE);
    ELSE
        // 🧱 L'erreur 64 (escalade / poussée anormale en butée) ne s'active QUE SI :
        // 1. On est sur le capteur Trémie (LimitSwitchFwd) ET qu'on continue d'insister en Marche Avant (Direction = 1) avec vitesse/commande variateur active.
        // 2. OU qu'on est sur le capteur Maintenance (LimitSwitchRev) ET qu'on continue d'insister en Marche Arrière (Direction = -1) avec vitesse/commande variateur active.
        OverrunCondition := (LimitSwitchFwd AND (Direction = 1) AND (ABS(DriveActualFreqHz) > 0.5 OR DriveStatusWord.0))
                         OR (LimitSwitchRev AND (Direction = -1) AND (ABS(DriveActualFreqHz) > 0.5 OR DriveStatusWord.0));

        TonLimitSwitchOverrun(IN := OverrunCondition, PT := T#1S500MS);

        IF TonLimitSwitchOverrun.Q THEN
            Status.ErrorId := Status.ErrorId OR 16#0040; // Défaut escalade confirmé (coupure puissance amont)
        ELSE
            // Si la poussée dans le mauvais sens cesse (ou si on repart en arrière), le défaut s'auto-efface
            Status.ErrorId := Status.ErrorId AND 16#FFBF;
        END_IF;
    END_IF;

    // 🔍 3septies. INCOHÉRENCE MOT CAPTEURS POSITION (bit7)
    IF (BypassSafety OR BypassSensorIncoherent) THEN
        // Nettoye le bit 7 résiduel
        Status.ErrorId := Status.ErrorId AND 16#FF7F;
    ELSE
        IF SensorWordIncoherent THEN
            Status.ErrorId := Status.ErrorId OR 16#0080;
        END_IF;
    END_IF;
    IF ResetEdge.Q THEN Status.ErrorId := Status.ErrorId AND 16#FF7F; END_IF;

END_IF; // fin IF NOT BypassGlobal

{endregion}

{region "§4 Arbitrage sorties et etat"}
// 📤 4. ARBITRAGE DES SORTIES MAÎTRESSES
Status.Error := (Status.ErrorId <> 16#0000);
ErrorEdge(CLK := Status.Error);
IF ErrorEdge.Q THEN
    Status.StateAtError := Status.State;
END_IF;

SafeStop := Status.Error OR NOT PowerContactorEngaged;

// PowerCutOff actif si thermique frein (bit3), incohérence arrêt (bit4),
// mouvement non commandé (bit5), dépassement de fin de course (bit6),
// ou incohérence mot capteurs position (bit7)
PowerCutOff := (Status.ErrorId AND 16#00F8) <> 16#0000;

// Décapsulage du bitfield Status.ErrorId pour l'IHM
ErrorOperatorComm   := (Status.ErrorId AND 16#0001) <> 16#0000;
ErrorDriveComm      := (Status.ErrorId AND 16#0002) <> 16#0000;
ErrorPhaseRotation  := (Status.ErrorId AND 16#0004) <> 16#0000;
ErrorBrakeThermal   := (Status.ErrorId AND 16#0008) <> 16#0000;
ErrorMecaB          := (Status.ErrorId AND 16#0010) <> 16#0000;
ErrorMecaA          := (Status.ErrorId AND 16#0020) <> 16#0000;
ErrorLimitSwitch    := (Status.ErrorId AND 16#0040) <> 16#0000;
ErrorSensorIncoherent := (Status.ErrorId AND 16#0080) <> 16#0000;

Status.Busy := FALSE;
Status.Done := FALSE;

// 🚦 5. STATE MACHINE (phase diagnostic)
Status.State := E_State.READY;


{endregion}

// === IMPLEMENTATION ===

{region "§1 Gate et initialisation"}
// 🛑 1. GATE (Enable / PowerContactorEngaged) — neutralisation totale, sorties sûres
IF NOT Enable OR NOT PowerContactorEngaged THEN
    RequestedDriveControlWord := 0; RequestedDriveFreqHz := 0.0;

    Brake(Enable := FALSE, Reset := FALSE, MovementRequested := FALSE, ContactorFeedback := BrakeFeedback,
          DelayContactClose := BrakeDelayContactClose, DelayMagnetise := BrakeDelayMagnetise,
          DelayMotorDecel := BrakeDelayMotorDecel, FeedbackTimeout := BrakeFeedbackTimeout);
    BrakeReleaseRequest := Brake.BrakeCmd;
    BrakeCommandOpenConfirmed := Brake.BrakeCommandOpenConfirmed;
    BrakeContactorCheck := Brake.ContactorCheck;

    CommandedDirection := 0;
    DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    SpeedRamp(Target := 0.0, AccelRate := CfgRampAccelRate, DecelRate := CfgRampDecelFastRate, CycleTimeS := CycleTimeCalc.CycleTimeS);

    ArrivalLock := FALSE;

    Status.State := E_State.DISABLED;
    Ready := FALSE; Status.Busy := FALSE; Status.Done := FALSE;
    TargetReached := FALSE; // 📊 Neutralisation : aucune cible atteinte garantie hors Enable
    RETURN;
END_IF;

// 🧹 Initialisation au premier scan : purge des résidus RAM d'un Online Change / Warm Start et évitement des alarmes transitoires
IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    Status.ErrorId := 16#0000;
    RETURN;
END_IF;

{endregion}

{region "§2 Acquisition commandes et position cible"}
Ready := TRUE;
CycleTimeCalc(DefaultValueS := 0.010);   // MainTask = 10 ms

// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 📡 3. CAPTEUR POSITION CIBLE (debounce)
CaptorDebounceTon(IN := PositionSensorTarget, PT := CaptorDebounce);
TargetReached := CaptorDebounceTon.Q;

{endregion}

{region "§4 Consigne vitesse ralentissement verrou arrivee"}
// ⚙️ 4. CORE — arbitrage rampe : Enable > SafeStop > StartStop
// DirectionChangePending FORCE la cible à 0.0 dès qu'une inversion de sens est en attente —
// sans cela, la cible suit la magnitude joystick en continu et ne croise jamais le seuil
// d'arrêt (0.1%) qui autorise l'interlock §5 à basculer CommandedDirection. Une inversion
// plus rapide que la décélération réelle bloquerait indéfiniment le mouvement dans l'ancien sens.
DirectionChangePending := (Direction <> CommandedDirection) AND (CommandedDirection <> 0);

RampTargetPct := 0.0;
IF NOT SafeStop AND StartStop AND NOT DirectionChangePending THEN
    // Si butée fin de course extrême atteinte dans le sens de marche demandé, consigne forcée à 0
    // 🌐 BypassLimitSwitch = TRUE → ignore cette protection
    IF NOT BypassLimitSwitch AND ((Direction = 1 AND LimitSwitchFwd) OR (Direction = -1 AND LimitSwitchRev)) THEN
        RampTargetPct := 0.0;
    ELSE
        RampTargetPct := ABS(SpeedTgt_Pct);
        // 🎚️ Consigne minimale joystick (1.0 Hz) : si un mouvement est demandé (SpeedTgt_Pct > 0.0), la consigne est au moins égale à 1.0 Hz
        IF RampTargetPct > 0.0 THEN
            RampTargetPct := MAX(RampTargetPct, (1.0 / SEL(DriveFreqScaleMaxHz > 0.0, 60.0, DriveFreqScaleMaxHz)) * 100.0);
        END_IF;
    END_IF;
END_IF;

// ⏱️ 4bis. RALENTISSEMENT AUTO À L'APPROCHE (piloté par capteur)
// Chaque capteur "un cran avant" la cible finale déclenche SA propre vitesse réduite, dans SON
// sens de marche uniquement — le ralentissement ne se déclenche qu'à l'approche de sa cible :
//   PV       + Direction=1  → approche Trémie
//   P1       + Direction=-1 → approche Maintenance
//   P2       + Direction=-1 → approche P1 (arrêt propre pour travail)
IF (Direction = 1) AND SlowdownSensorTremie THEN
    RampTargetPct := LIMIT(0.0, RampTargetPct, (ApproachSpeedTremieHz / SEL(DriveFreqScaleMaxHz > 0.0, 60.0, DriveFreqScaleMaxHz)) * 100.0);
END_IF;
IF (Direction = -1) AND SlowdownSensorMaintenance THEN
    RampTargetPct := LIMIT(0.0, RampTargetPct, (ApproachSpeedMaintenanceHz / SEL(DriveFreqScaleMaxHz > 0.0, 60.0, DriveFreqScaleMaxHz)) * 100.0);
END_IF;
IF (Direction = -1) AND SlowdownSensorP1 THEN
    RampTargetPct := LIMIT(0.0, RampTargetPct, (ApproachSpeedP1Hz / SEL(DriveFreqScaleMaxHz > 0.0, 60.0, DriveFreqScaleMaxHz)) * 100.0);
END_IF;

// 🎯 4ter. VERROUILLAGE ANTI-REBONDS SENS EN BUTÉE (Trémie, P1, Maintenance, Fdc extrêmes)
// Dès qu'on touche un capteur d'arrêt (TargetReached, débounce 100ms) OU un fin de course dur
// (LimitSwitchFwd/Rev, §5bis — immédiat, non débounce, mais toute activation même brève arme le
// même verrou), le sens d'arrivée (DirectionAtArrival) est MÉMORISÉ et BLOQUÉ. Toute activation,
// même un instant, arme DirectionAtArrival comme un TargetReached — un Fdc qui s'ouvre quelques ms
// pendant le freinage ne doit pas laisser la rampe (encore haute en interne) revenir en sortie.
ArrivalEdge(CLK := TargetReached
                 OR (LimitSwitchFwd AND (CommandedDirection = 1))
                 OR (LimitSwitchRev AND (CommandedDirection = -1)));
IF ArrivalEdge.Q THEN
    DirectionAtArrival := CommandedDirection;
END_IF;

// Un retour au neutre, même SOUTENU (>100ms), ne doit JAMAIS lever le verrou — seul un vrai
// changement de sens (dégagement volontaire, sans ambiguïté) le fait. Sinon, un neutre 100ms+
// puis un réappui dans le MÊME sens (le capteur/Fdc restant au niveau haut en continu,
// TargetReached ne montre plus de front) contournerait le verrou et M3 repartirait vers la butée.
// On doit repartir dans l'AUTRE sens, jamais juste relâcher-réappuyer pareil. Instantané, jamais
// retardé (le dégagement doit rester rapide).
IF (Direction = DirectionAtArrival * (-1)) OR ResetEdge.Q OR (NOT TargetReached AND NOT LimitSwitchFwd AND NOT LimitSwitchRev) THEN
    DirectionAtArrival := 0;
END_IF;

// Bloque la consigne à 0 tant que l'ordre demande d'insister dans le sens d'arrivée verrouillé
ArrivalLock := (DirectionAtArrival <> 0) AND (Direction = DirectionAtArrival);
IF ArrivalLock THEN
    RampTargetPct := 0.0;
END_IF;

SpeedRamp(Target := RampTargetPct,
          AccelRate := CfgRampAccelRate,
          DecelRate := SEL(SafeStop, CfgRampDecelNormalRate, CfgRampDecelFastRate),
          CycleTimeS := CycleTimeCalc.CycleTimeS);

{endregion}

{region "§5 Interlock changement sens"}
// 🔒 5. INTERLOCK CHANGEMENT DE SENS — jamais Fwd+Rev simultanés (vitesse confirmée nulle)
IF Direction <> CommandedDirection THEN
    IF CommandedDirection = 0 AND Direction <> 0 THEN
        CommandedDirection := Direction;
        DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    ELSIF ABS(SpeedRamp.Current) < 0.1 THEN
        DirectionChangeDelay(IN := TRUE, PT := DirectionInterlockDelay);
        IF DirectionChangeDelay.Q THEN
            CommandedDirection := Direction;
            DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
        END_IF;
    ELSE
        DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    END_IF;
ELSE
    DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
END_IF;

{endregion}

{region "§5bis Commande variateur et protections fin course"}
// 🛑 Pilotage du frein : le mouvement est considéré actif tant que la consigne est supérieure à 0.1%
// OU que la fréquence réelle mesurée du variateur M3 est >= 1.0 Hz.
// Le frein de parking ne serre QUE lorsque la fréquence réelle variateur chute sous 1.0 Hz !
// Borné par un garde-fou 2s — DriveActualFreqHz n'a aucun contrôle de fraîcheur EtherCAT ; si la
// communication se fige sur une valeur ≥1.0 Hz (perte réseau en mouvement), rien d'autre en aval
// ne referme le frein (FB_TranslationOutputInterlock ignore volontairement SafeStop par
// conception). Le garde-fou force la fermeture du frein 2s après la fin de la rampe THÉORIQUE, quoi
// que dise la mesure réelle — combine attente réelle (évite un serrage sur arbre encore tournant)
// et certitude de fermeture (n'attend jamais indéfiniment).
TonBrakeRealFreqTimeout(IN := NOT ((CommandedDirection <> 0) AND (ABS(SpeedRamp.Current) > 0.1)), PT := T#2s);
MovementRequested := ((CommandedDirection <> 0) AND (ABS(SpeedRamp.Current) > 0.1))
                     OR (ABS(DriveActualFreqHz) >= 1.0 AND NOT TonBrakeRealFreqTimeout.Q);

// 🔀 5bis. SORTIE PHYSIQUE (ETHERCAT)
RequestedDriveFreqHz := (ABS(SpeedRamp.Current) / 100.0) * DriveFreqScaleMaxHz;

// Compensation câblage moteur appliquée ICI SEULEMENT, sur le mot de commande —
// CommandedDirection (sécurité/capteurs juste au-dessus, §4/§4bis/§4ter) reste le sens réel.
PhysicalDriveDirection := SEL(InvertDriveDirection, CommandedDirection, CommandedDirection * (-1));

// Pilotage nominal Given Command 1 (0x3101) :
// 0: None, 1: Forward, 2: Reverse, 7: Reset
IF Reset THEN
    RequestedDriveControlWord := 7; // Reset défaut variateur
ELSIF Status.Error THEN
    RequestedDriveControlWord := 0; // Arrêt sur défaut
ELSIF MovementRequested THEN
    IF PhysicalDriveDirection = 1 THEN
        RequestedDriveControlWord := 1; // Marche avant
    ELSIF PhysicalDriveDirection = -1 THEN
        RequestedDriveControlWord := 2; // Marche arrière
    ELSE
        RequestedDriveControlWord := 0;
    END_IF;
ELSE
    RequestedDriveControlWord := 0;
END_IF;

// Sécurité : si Fdc extrême atteint dans le sens de marche, coupure commande immédiate (sans rampe ni couple)
// 🌐 BypassLimitSwitch = TRUE → ignore cette protection (test/mise en service)
IF NOT BypassLimitSwitch AND ((CommandedDirection = 1 AND LimitSwitchFwd) OR (CommandedDirection = -1 AND LimitSwitchRev)) THEN
    RequestedDriveControlWord := 0;
    RequestedDriveFreqHz := 0.0;
    SpeedRamp(Target := 0.0, AccelRate := 0.0, DecelRate := 100000.0, CycleTimeS := 1.0);
END_IF;

{endregion}

{region "§6 Commande frein"}
// 🛑 6. FREIN (composé, réutilisé tel quel)
Brake(Enable := TRUE, Reset := Reset, MovementRequested := MovementRequested,
      ContactorFeedback := BrakeFeedback,
      DelayContactClose := BrakeDelayContactClose, DelayMagnetise := BrakeDelayMagnetise,
      DelayMotorDecel := BrakeDelayMotorDecel, FeedbackTimeout := BrakeFeedbackTimeout,
      BypassContactorCheck := BypassContactorCheck);
BrakeReleaseRequest := Brake.BrakeCmd;
BrakeCommandOpenConfirmed := Brake.BrakeCommandOpenConfirmed;
BrakeContactorCheck := Brake.ContactorCheck;

// 🛡️ FB_Translation ne décide plus la frontière finale : il expose uniquement
// ses demandes métier. SafeStop est déjà appliqué dans la rampe rapide §4 : tant que
// la vitesse ne vaut pas zéro, la demande et le desserrage suivent la décélération.
// FB_TranslationOutputInterlock ne doit jamais transformer SafeStop en coupure sèche.

{endregion}

{region "§7 Diagnostic etat et repli defaut"}
// 🧾 7. ERRORID (bitfield, cumul)
IF Brake.Status.Error THEN
    Status.ErrorId := Status.ErrorId OR 16#0001;
ELSIF ResetEdge.Q THEN
    Status.ErrorId := Status.ErrorId AND 16#FFFE;
END_IF;

// Défaut variateur (bit3) : lu via EtherCAT (DriveStatusWord.4)
IF DriveStatusWord.4 THEN
    Status.ErrorId := Status.ErrorId OR 16#0008;
ELSIF ResetEdge.Q THEN
    Status.ErrorId := Status.ErrorId AND 16#FFF7;
END_IF;

// 🚧 Défaut fin de course extrême (bit6) — si bypassé, on NETTOIE le bit résiduel
IF BypassLimitSwitch THEN
    Status.ErrorId := Status.ErrorId AND 16#FFBF;   // Nettoie le bit 6 (évite résidu d'avant activation)
ELSE
    // Activé UNIQUEMENT en cas de tentative d'avancer vers la butée active (libéré si dégagement en sens inverse)
    IF (CommandedDirection = 1 AND LimitSwitchFwd) OR (CommandedDirection = -1 AND LimitSwitchRev) THEN
        Status.ErrorId := Status.ErrorId OR 16#0040;
    ELSE
        Status.ErrorId := Status.ErrorId AND 16#FFBF;
    END_IF;
END_IF;

Status.Error := (Status.ErrorId <> 16#0000);
ErrorEdge(CLK := Status.Error);
IF ErrorEdge.Q THEN
    Status.StateAtError := Status.State;
END_IF;

// 🚦 8. STATE MACHINE (phase)
IF (NOT StartStop OR SafeStop) AND ABS(SpeedRamp.Current) > 0.1 THEN
    Status.State := E_State.STOPPING;
ELSIF ABS(SpeedRamp.Current) > 0.1 THEN
    Status.State := E_State.BUSY;
ELSE
    Status.State := E_State.READY;
END_IF;

Status.Busy := (Status.State = E_State.BUSY) OR (Status.State = E_State.STOPPING);
Status.Done := FALSE;

// 🛡️ 9. SORTIE SÛRE SUR DÉFAUT
IF Status.Error THEN
    RequestedDriveControlWord := 0; RequestedDriveFreqHz := 0.0;
    BrakeReleaseRequest := FALSE;
END_IF;

{endregion}

// === IMPLEMENTATION ===

{region "§1 Assemblage mot et cohérence"}
// 🧾 Assemblage du mot (bit4=Trémie ... bit0=Maintenance, ordre doc AF_Partie-02 §3bis)
SensorsWord := 0;
IF SensorTremie      THEN SensorsWord := SensorsWord OR 16#10; END_IF;
IF SensorPV          THEN SensorsWord := SensorsWord OR 16#08; END_IF;
IF SensorP2          THEN SensorsWord := SensorsWord OR 16#04; END_IF;
IF SensorP1          THEN SensorsWord := SensorsWord OR 16#02; END_IF;
IF SensorMaintenance THEN SensorsWord := SensorsWord OR 16#01; END_IF;

// 🎯 Les 6 combinaisons valides (progression monotone décroissante Trémie→Maintenance)
CASE SensorsWord OF
    2#11111, 2#01111, 2#00111, 2#00011, 2#00001, 2#00000:
        Incoherent := FALSE;
    ELSE
        Incoherent := TRUE;
END_CASE;

// 🚧 Limites extrêmes — uniquement sur mot valide (évite un Fdc fantôme déclenché par une incohérence)
LimitSwitchFwd := (NOT Incoherent) AND (SensorsWord = 2#11111);
LimitSwitchRev := (NOT Incoherent) AND (SensorsWord = 2#00000);
{endregion}

{region "§2 Reprise capteurs"}
// Reprise des capteurs de position pour les consommateurs aval (passthrough, identique à l'entrée filtrée)
// ⚠️ CUMULATIF — voir avertissement en déclaration, réservé au ralentissement d'approche.
TranslationPosTremie      := SensorTremie;
TranslationPosPV          := SensorPV;
TranslationPosP2          := SensorP2;
TranslationPosP1          := SensorP1;
TranslationPosMaintenance := SensorMaintenance;
{endregion}

{region "§3 Fronts individuels"}
// Front individuel par capteur — voir avertissement en déclaration. Transitoire (1 cycle),
// mémorisé par l'appelant.
EdgeUpTremie(CLK := SensorTremie);           EdgeDnTremie(CLK := SensorTremie);
EdgeUpPV(CLK := SensorPV);                   EdgeDnPV(CLK := SensorPV);
EdgeUpP2(CLK := SensorP2);                   EdgeDnP2(CLK := SensorP2);
EdgeUpP1(CLK := SensorP1);                   EdgeDnP1(CLK := SensorP1);
EdgeUpMaintenance(CLK := SensorMaintenance); EdgeDnMaintenance(CLK := SensorMaintenance);

// Front du capteur PROPRE à chaque position — voir modèle en déclaration.
// Extrémités : un seul sens valide chacune. Points intermédiaires : les deux fronts de LEUR PROPRE
// capteur (montant = atteint en venant de Maintenance, descendant = dépassé en venant de Trémie).
TranslationAtTremie      := EdgeUpTremie.Q;
TranslationAtPV          := EdgeUpPV.Q OR EdgeDnPV.Q;
TranslationAtP2          := EdgeUpP2.Q OR EdgeDnP2.Q;
TranslationAtP1          := EdgeUpP1.Q OR EdgeDnP1.Q;
TranslationAtMaintenance := EdgeDnMaintenance.Q;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Gate et initialisation"}
IF NOT Enable THEN
    Recalibrated := FALSE;
    RecalibratedSensorId := -1;
    // 🔒 Sorties odométriques VOLONTAIREMENT conservées hors Enable (AC3 / persistance continue RETAIN) :
    // - PositionEstimatedM & Initialized : estimation odométrique et référence absolue maintenues pour ne pas perdre la position M3 hors Enable
    RETURN;
END_IF;

IF ColdStart THEN
    PositionEstimatedM := PersistedPositionM;
    Initialized := PersistedInitialized;
    ColdStart := FALSE;
END_IF;

CycleTimeCalc(DefaultValueS := 0.010);
Recalibrated := FALSE;
{endregion}

{region "§2 Fronts capteurs"}
// 1. Détection des fronts montants sur franchissement des capteurs fixes
TrigTremie(CLK := SensorTremie);
TrigPV(CLK := SensorPV);
TrigP2(CLK := SensorP2);
TrigP1(CLK := SensorP1);
TrigMaintenance(CLK := SensorMaintenance);
{endregion}

{region "§3 Recalage et intégration"}
// 2. Recalage absolu sur franchissement capteur — UNIQUEMENT après le premier scan utile.
//    Au 1er scan, un capteur "déjà présent" à l'initialisation (sim démarre à la trémie :
//    5 capteurs actifs) n'est pas un franchissement réel ; sinon le recalage IF/ELSIF
//    partirait de Maintenance (premier dans l'ordre) et écraserait la position à 30 m.
IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
ELSE
    IF TrigMaintenance.Q THEN
        PositionEstimatedM := PosMaintenanceM;
        Recalibrated := TRUE;
        RecalibratedSensorId := 0;
    ELSIF TrigP1.Q THEN
        PositionEstimatedM := PosP1M;
        Recalibrated := TRUE;
        RecalibratedSensorId := 1;
    ELSIF TrigP2.Q THEN
        PositionEstimatedM := PosP2M;
        Recalibrated := TRUE;
        RecalibratedSensorId := 2;
    ELSIF TrigPV.Q THEN
        PositionEstimatedM := PosPVM;
        Recalibrated := TRUE;
        RecalibratedSensorId := 3;
    ELSIF TrigTremie.Q THEN
        PositionEstimatedM := PosTremieM;
        Recalibrated := TRUE;
        RecalibratedSensorId := 4;
    END_IF;
END_IF;

// 3. Initialisation au tout premier démarrage sur le premier capteur actif vu (si non initialisé)
IF NOT Initialized THEN
    IF SensorTremie THEN PositionEstimatedM := PosTremieM; Initialized := TRUE;
    ELSIF SensorPV THEN PositionEstimatedM := PosPVM; Initialized := TRUE;
    ELSIF SensorP2 THEN PositionEstimatedM := PosP2M; Initialized := TRUE;
    ELSIF SensorP1 THEN PositionEstimatedM := PosP1M; Initialized := TRUE;
    ELSIF SensorMaintenance THEN PositionEstimatedM := PosMaintenanceM; Initialized := TRUE;
    END_IF;
END_IF;

// 4. Intégration temporelle continue (Odométrie cycle par cycle)
// dX = -Direction * (FreqHz * Gain) * dt — convention 0 m=Trémie, 30 m=Maintenance :
// le sens +1 (vers Trémie) DÉCROÎT la position vers 0 m, le sens -1 (vers Maintenance) la CROÎT vers 30 m.
IF Direction <> 0 AND DriveActualFreqHz > 0.1 THEN
    PositionEstimatedM := PositionEstimatedM - (INT_TO_REAL(Direction) * DriveActualFreqHz * GainMetersPerHzSec * CycleTimeCalc.CycleTimeS);
END_IF;
{endregion}

{region "§4 Bornage"}
// Bornage de sécurité pour éviter la dérive infinie hors rail
// Convention 0 m=Trémie, 30 m=Maintenance : bornage [Trémie-0.5, Maintenance+0.5].
PositionEstimatedM := LIMIT(PosTremieM - 0.5, PositionEstimatedM, PosMaintenanceM + 0.5);
{endregion}

{region "§1 Gate"}
// 🛑 1. GATE — pas d'Enable = frein collé (sécurité positive), aucune temporisation en cours
IF NOT Enable THEN
    TonMagnetise(IN := FALSE, PT := DelayMagnetise + DelayContactClose);
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    BrakeCmd := FALSE;
    Status.State := E_State.DISABLED;
    Ready := FALSE; Status.Busy := FALSE; Status.Done := FALSE;
    ContactorCheck.Command := FALSE;          // 📊 Neutralisation : miroir de BrakeCmd := FALSE
    ContactorCheck.Feedback := ContactorFeedback; // 📊 Neutralisation : miroir entrée physique
    // 🔒 ContactorCheck.StuckClosed / StuckOpen et Status.ErrorId conservés (latch défaut, acquittement requis)
    BrakeCommandOpenConfirmed := FALSE;       // 🛡️ Fail-Safe : frein commandé fermé hors Enable
    RETURN;
END_IF;

Ready := TRUE;
{endregion}

{region "§2 Reset et fronts"}
// 🔑 2. RESET FRONT — efface le bit dont la cause a disparu
ResetEdge(CLK := Reset);
BypassEdge(CLK := BypassContactorCheck);
{endregion}

{region "§3 Séquence temporisée"}
// 🛠️ 3. SÉQUENCE TEMPORISÉE (démarrage vs arrêt)
IF MovementRequested THEN
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    TonMagnetise(IN := TRUE, PT := DelayMagnetise + DelayContactClose);
    IF TonMagnetise.Q THEN
        BrakeCmd := TRUE;              // ✅ Contacteur + magnétisation acquis → relâche
        Status.State := E_State.DONE;
    ELSE
        BrakeCmd := FALSE;             // ⏳ Encore collé pendant la magnétisation
        Status.State := E_State.BUSY;
    END_IF;
ELSE
    // Sécurité positive : fermeture immédiate du frein (collé) dès que les contacteurs de sens s'ouvrent
    TonMagnetise(IN := FALSE, PT := DelayMagnetise + DelayContactClose);
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    BrakeCmd := FALSE;                 // Fermeture immédiate
    Status.State := E_State.READY;
END_IF;

Status.Busy := (Status.State = E_State.BUSY);
Status.Done := (Status.State = E_State.DONE);
{endregion}

{region "§4 Double vérification contacteur"}
// 🔍 4. DOUBLE VÉRIFICATION RETOUR CONTACTEUR (ST_ContactorCheck)
ContactorCheck.Command := BrakeCmd;
ContactorCheck.Feedback := ContactorFeedback;

// ContactorFeedback est dans le MÊME sens que BrakeCmd (TRUE = relâché = frein ouvert).
// En marche saine les deux sont ÉGAUX → c'est leur DIFFÉRENCE qui signale l'incohérence
// (contacteur collé). Le test compare donc `<>`.
TonFeedback(IN := (BrakeCmd <> ContactorFeedback), PT := FeedbackTimeout);
IF NOT BypassContactorCheck THEN
    IF TonFeedback.Q THEN
        ContactorCheck.StuckClosed := (BrakeCmd AND NOT ContactorFeedback);            // relâche commandée (BrakeCmd=TRUE), frein reste serré (ContactorFeedback=FALSE)
        ContactorCheck.StuckOpen   := (NOT BrakeCmd AND ContactorFeedback);             // serrage commandé (BrakeCmd=FALSE), frein reste ouvert (ContactorFeedback=TRUE)
        Status.ErrorId := Status.ErrorId OR 16#0001;
    ELSIF ResetEdge.Q THEN
        ContactorCheck.StuckClosed := FALSE;
        ContactorCheck.StuckOpen   := FALSE;
        Status.ErrorId := Status.ErrorId AND 16#FFFE;
    END_IF;
ELSE
    ContactorCheck.StuckClosed := FALSE;
    ContactorCheck.StuckOpen   := FALSE;
    Status.ErrorId := Status.ErrorId AND 16#FFFE;   // Bypass actif : efface/maintient à 0 le bit 0
    IF BypassEdge.Q THEN
        Status.StateAtError := E_State.DISABLED; // Front activation bypass : débloque l'état figé
    END_IF;
END_IF;

{endregion}

{region "§5 Arbitrage error"}
// 🧾 5. ARBITRAGE ERROR / STATEATERROR (figé jusqu'à acquittement)
Status.Error := (Status.ErrorId <> 16#0000);
ErrorEdge(CLK := Status.Error);
IF ErrorEdge.Q THEN
    Status.StateAtError := Status.State;
END_IF;
{endregion}

{region "§6 Sortie sûre"}
// 🛡️ 6. SORTIE SÛRE SUR DÉFAUT
IF Status.Error THEN
    BrakeCmd := FALSE;
END_IF;
{endregion}

{region "§7 Confirmation ouverture"}
// 📤 7. CONFIRMATION OUVERTURE FREIN (même sens que ContactorFeedback, ou image de BrakeCmd si BypassContactorCheck=TRUE)
IF BypassContactorCheck THEN
    BrakeCommandOpenConfirmed := BrakeCmd;
ELSE
    BrakeCommandOpenConfirmed := ContactorFeedback;  (* TRUE = frein ouvert = desserrage confirmé *)
END_IF;
{endregion}

{region "§1 Acquisition temps"}
// 1. ACQUISITION DU TEMPS SYSTÈME
TimeCurrent := TIME();
{endregion}

{region "§2 Initialisation"}
// 2. INITIALISATION UNIQUE AU PREMIER CYCLE
IF NOT InitDone THEN
    TimeLast := TimeCurrent;
    InitDone := TRUE;
    CycleTimeS := DefaultValueS;
    RETURN;
END_IF;
{endregion}

{region "§3 Calcul delta"}
// 3. CALCUL DU DELTA EN MILLISECONDES
DeltaTimeMs := TIME_TO_UDINT(TimeCurrent - TimeLast);
{endregion}

{region "§4 Conversion et secours"}
// 4. CONVERSION ET CHARGE DE SECOURS
IF DeltaTimeMs > 0 THEN
    CycleTimeS := UDINT_TO_REAL(DeltaTimeMs) / 1000.0;
ELSE
    CycleTimeS := DefaultValueS;
END_IF;
{endregion}

{region "§5 Archivage"}
// 5. ARCHIVAGE POUR LE PROCHAIN CYCLE
TimeLast := TimeCurrent;
{endregion}

// Détection du comportement (Accélération vs Décélération)
// Classification par CÔTÉ DE ZÉRO + sens de déplacement, plus par signe brut de Target seul
// (robuste à une traversée de zéro rapide).
// 🛡️ Garde-fou : la rampe ne sort jamais de la plage normalisée ±100 %.
TargetLimited := LIMIT(-100.0, Target, 100.0);
Current := LIMIT(-100.0, Current, 100.0);

IF (Current >= 0.0 AND TargetLimited >= Current) OR (Current <= 0.0 AND TargetLimited <= Current) THEN
    StepX := AccelRate * CycleTimeS; // S'éloigne du zéro (reste du même côté, va plus loin)
ELSE
    StepX := DecelRate * CycleTimeS; // Retourne vers zéro, ou le traverse vers l'autre signe
END_IF;

// Application de la rampe
IF Current < TargetLimited THEN
    Current := Current + StepX;
    IF Current > TargetLimited THEN Current := TargetLimited; END_IF;
ELSIF Current > TargetLimited THEN
    Current := Current - StepX;
    IF Current < TargetLimited THEN Current := TargetLimited; END_IF;
END_IF;

// 🛡️ Limitation finale : même une valeur d'état déjà corrompue reste bornée.
Current := LIMIT(-100.0, Current, 100.0);
